def write_batch(ids, label):
    assert set(ids) <= set(P), (label, set(ids) - set(P))
    for cid in ids:
        d = P[cid]
        obj = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
               "confidence": d["confidence"], "trigger": d["trigger"]}
        assert set(obj) == {"case_id","prediction_text","basis","confidence","trigger"}
        assert 0 <= obj["confidence"] <= 1
        tr = obj["trigger"]
        assert set(tr) == {"changed_main","reserve_used","disputed","reason"}
        assert all(isinstance(tr[k], bool) for k in ("changed_main","reserve_used","disputed"))
        assert isinstance(tr["reason"], str)
        (OUT / f"{cid}.json").write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")
    print(label, "written", len(ids))

